import React from "react";
import "./../css/index.css";
import { FaRegBell } from "react-icons/fa";

import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class Home extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      authChecking: true,
      authenticated: false,

      loading: true,

      cities: [],
      repairmen: [],

      cityLimit: 3,
      cityPeriod: "week",

      repairmanLimit: 3,
      repairmanPeriod: "week",
    };
  }

  componentDidMount() {
    const isAuthenticated = AuthCheck();

    if (!isAuthenticated) {
      return;
    }

    this.setState(
      {
        authChecking: false,
        authenticated: true,
      },
      () => {
        this.getHome();
      }
    );
  }

  // =====================================================
  // دریافت اطلاعات Home
  // =====================================================

  getHome = () => {
    const token = localStorage.getItem("token");

    this.setState({
      loading: true,
    });

    fetch(`${API_URL}/home`, {
      method: "GET",

      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then(async (response) => {
        const data = await response.json();

        console.log("========== HOME RESPONSE ==========");
        console.log(data);
        console.log("KEYS:", Object.keys(data || {}));
        console.log("===================================");

        if (!response.ok) {
          throw new Error(
            data?.message || "خطا در دریافت اطلاعات صفحه اصلی"
          );
        }

        return data;
      })
      .then((data) => {
        /*
         * =================================================
         * پیدا کردن لیست شهرها
         * =================================================
         */

        let cities = [];

        if (Array.isArray(data)) {
          cities = data;
        } else if (Array.isArray(data.cities)) {
          cities = data.cities;
        } else if (Array.isArray(data.city)) {
          cities = data.city;
        } else if (Array.isArray(data.popularCities)) {
          cities = data.popularCities;
        } else if (Array.isArray(data.popular_cities)) {
          cities = data.popular_cities;
        } else if (Array.isArray(data.data?.cities)) {
          cities = data.data.cities;
        } else if (Array.isArray(data.data?.city)) {
          cities = data.data.city;
        } else if (Array.isArray(data.data?.popularCities)) {
          cities = data.data.popularCities;
        } else if (Array.isArray(data.result?.cities)) {
          cities = data.result.cities;
        } else if (Array.isArray(data.result?.city)) {
          cities = data.result.city;
        }

        /*
         * =================================================
         * پیدا کردن لیست تعمیرکاران
         * =================================================
         */

        let repairmen = [];

        if (Array.isArray(data.repairmen)) {
          repairmen = data.repairmen;
        } else if (Array.isArray(data.users)) {
          repairmen = data.users;
        } else if (Array.isArray(data.user)) {
          repairmen = data.user;
        } else if (Array.isArray(data.activeRepairmen)) {
          repairmen = data.activeRepairmen;
        } else if (Array.isArray(data.active_repairmen)) {
          repairmen = data.active_repairmen;
        } else if (Array.isArray(data.data?.repairmen)) {
          repairmen = data.data.repairmen;
        } else if (Array.isArray(data.data?.users)) {
          repairmen = data.data.users;
        } else if (Array.isArray(data.data?.user)) {
          repairmen = data.data.user;
        } else if (Array.isArray(data.data?.activeRepairmen)) {
          repairmen = data.data.activeRepairmen;
        } else if (Array.isArray(data.result?.repairmen)) {
          repairmen = data.result.repairmen;
        } else if (Array.isArray(data.result?.users)) {
          repairmen = data.result.users;
        }

        /*
         * =================================================
         * اگر API یک آرایه مشترک برگرداند
         *
         * تشخیص تعمیرکار از روی reqs7 / reqs30
         * =================================================
         */

        if (
          repairmen.length === 0 &&
          Array.isArray(data.data)
        ) {
          const detectedRepairmen = data.data.filter(
            (item) =>
              item &&
              (
                item.reqs7 !== undefined ||
                item.reqs30 !== undefined ||
                item.reqs90 !== undefined ||
                item.reqs180 !== undefined
              )
          );

          if (detectedRepairmen.length > 0) {
            repairmen = detectedRepairmen;
          }
        }

        console.log("CITIES:", cities);
        console.log("REPAIRMEN:", repairmen);

        this.setState({
          cities: cities,
          repairmen: repairmen,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("HOME ERROR:", error);

        this.setState({
          cities: [],
          repairmen: [],
          loading: false,
        });
      });
  };

  // =====================================================
  // تعداد شهر
  // =====================================================

  handleCityLimitChange = (e) => {
    this.setState({
      cityLimit: Number(e.target.value),
    });
  };

  // =====================================================
  // بازه شهر
  // =====================================================

  handleCityPeriodChange = (e) => {
    this.setState({
      cityPeriod: e.target.value,
    });
  };

  // =====================================================
  // تعداد تعمیرکار
  // =====================================================

  handleRepairmanLimitChange = (e) => {
    this.setState({
      repairmanLimit: Number(e.target.value),
    });
  };

  // =====================================================
  // بازه تعمیرکار
  // =====================================================

  handleRepairmanPeriodChange = (e) => {
    this.setState({
      repairmanPeriod: e.target.value,
    });
  };

  // =====================================================
  // نام شهر
  // =====================================================

  getCityName = (city) => {
    if (typeof city === "string") {
      return city;
    }

    return (
      city.name ||
      city.city_name ||
      city.title ||
      city.city ||
      "بدون نام"
    );
  };

  // =====================================================
  // تعداد درخواست شهر
  // =====================================================

  getCityRequests = (city) => {
    const { cityPeriod } = this.state;

    if (cityPeriod === "week") {
      return Number(
        city.reqs7 ??
        city.requests7 ??
        city.count7 ??
        city.req7 ??
        city.count ??
        city.requests ??
        0
      );
    }

    if (cityPeriod === "month") {
      return Number(
        city.reqs30 ??
        city.requests30 ??
        city.count30 ??
        city.req30 ??
        city.count ??
        city.requests ??
        0
      );
    }

    if (cityPeriod === "year") {
      return Number(
        city.reqs365 ??
        city.requests365 ??
        city.req365 ??
        city.reqs180 ??
        city.requests180 ??
        city.req180 ??
        city.count ??
        city.requests ??
        0
      );
    }

    return 0;
  };

  // =====================================================
  // نام تعمیرکار
  // =====================================================

  getRepairmanName = (repairman) => {
    const firstName =
      repairman.name ||
      repairman.first_name ||
      "";

    const lastName =
      repairman.family ||
      repairman.last_name ||
      "";

    const fullName =
      `${firstName} ${lastName}`.trim();

    return fullName || "بدون نام";
  };

  // =====================================================
  // تعداد درخواست تعمیرکار
  // =====================================================

  getRepairmanRequests = (repairman) => {
    const { repairmanPeriod } = this.state;

    if (repairmanPeriod === "week") {
      return Number(
        repairman.reqs7 ?? 0
      );
    }

    if (repairmanPeriod === "month") {
      return Number(
        repairman.reqs30 ?? 0
      );
    }

    if (repairmanPeriod === "year") {
      /*
       * طبق اطلاعاتی که از API داریم:
       *
       * reqs7
       * reqs30
       * reqs90
       * reqs180
       *
       * برای یک سال اگر reqs365 وجود داشته باشد
       * از آن استفاده می‌کنیم.
       *
       * در غیر این صورت reqs180 استفاده می‌شود.
       */

      return Number(
        repairman.reqs365 ??
        repairman.reqs180 ??
        0
      );
    }

    return 0;
  };

  // =====================================================
  // عکس تعمیرکار
  // =====================================================

  getRepairmanImage = (repairman) => {
    const image =
      repairman.image ||
      repairman.img ||
      repairman.avatar ||
      repairman.profile_image ||
      repairman.profpic;

    if (!image) {
      const name =
        this.getRepairmanName(repairman);

      return `https://ui-avatars.com/api/?name=${encodeURIComponent(
        name
      )}&background=e9ecef&color=495057&size=40&rounded=true`;
    }

    /*
     * اگر آدرس کامل باشد
     */

    if (
      String(image).startsWith("http://") ||
      String(image).startsWith("https://")
    ) {
      return image;
    }

    /*
     * اگر مسیر نسبی باشد
     */

    return `https://iranaserviceapp.ir/test/${String(
      image
    ).replace(/^\/+/, "")}`;
  };

  render() {
    if (this.state.authChecking) {
      return <Loader />;
    }

    if (!this.state.authenticated) {
      return null;
    }

    const {
      cities,
      repairmen,
      cityLimit,
      cityPeriod,
      repairmanLimit,
      repairmanPeriod,
      loading,
    } = this.state;

    /*
     * =================================================
     * مرتب کردن شهرها
     * =================================================
     */

    const displayedCities = cities
      .slice()
      .sort(
        (a, b) =>
          this.getCityRequests(b) -
          this.getCityRequests(a)
      )
      .slice(0, cityLimit);

    /*
     * =================================================
     * مرتب کردن تعمیرکاران
     * =================================================
     */

    const displayedRepairmen = repairmen
      .slice()
      .sort(
        (a, b) =>
          this.getRepairmanRequests(b) -
          this.getRepairmanRequests(a)
      )
      .slice(0, repairmanLimit);

    return (
      <main className="container pt-5">

        {/* =================================================
            اعلان
        ================================================= */}

        <div className="fixed-top-left">
          <FaRegBell
            size={24}
            color="#495057"
          />
        </div>

        {/* =================================================
            شهرهای پر درخواست
        ================================================= */}

        <div className="card shadow-sm border-0 mb-4">

          <div className="card-body p-4">

            <h4 className="h6 fw-bold text-center mb-2">
              شهرهای پر درخواست
            </h4>

            <div className="d-flex justify-content-end gap-2 mb-3 row">

              <select
                value={cityLimit}
                onChange={
                  this.handleCityLimitChange
                }
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{
                  width: "auto",
                }}
              >
                <option value="3">
                  نمایش ۳ شهر
                </option>

                <option value="5">
                  نمایش ۵ شهر
                </option>

                <option value="10">
                  نمایش ۱۰ شهر
                </option>
              </select>

              <select
                value={cityPeriod}
                onChange={
                  this.handleCityPeriodChange
                }
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{
                  width: "auto",
                }}
              >
                <option value="week">
                  یک هفته گذشته
                </option>

                <option value="month">
                  یک ماه گذشته
                </option>

                <option value="year">
                  یک سال گذشته
                </option>
              </select>

            </div>

            <div className="scrollable-table">

              {loading ? (
                <div className="text-center text-muted py-4">
                  در حال دریافت اطلاعات...
                </div>
              ) : displayedCities.length === 0 ? (
                <div className="text-center text-muted py-4">
                  اطلاعاتی برای نمایش شهرها وجود ندارد.
                </div>
              ) : (
                <table className="table table-borderless mb-0">

                  <tbody>

                    {displayedCities.map(
                      (city, index) => (
                        <tr
                          key={
                            city.id ||
                            city.city_id ||
                            index
                          }
                        >

                          <td className="number-circle">
                            {index + 1}
                          </td>

                          <td className="text-end">
                            {this.getCityName(
                              city
                            )}
                          </td>

                        </tr>
                      )
                    )}

                  </tbody>

                </table>
              )}

            </div>

          </div>

        </div>

        {/* =================================================
            فعال ترین تعمیرکاران
        ================================================= */}

        <div className="card shadow-sm border-0">

          <div className="card-body p-4">

            <h4 className="h6 fw-bold text-center mb-2">
              فعال ترین تعمیرکاران
            </h4>

            <div className="d-flex justify-content-end gap-2 mb-3 row">

              <select
                value={repairmanLimit}
                onChange={
                  this.handleRepairmanLimitChange
                }
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{
                  width: "auto",
                }}
              >
                <option value="3">
                  نمایش ۳ نفر
                </option>

                <option value="5">
                  نمایش ۵ نفر
                </option>

                <option value="10">
                  نمایش ۱۰ نفر
                </option>
              </select>

              <select
                value={repairmanPeriod}
                onChange={
                  this.handleRepairmanPeriodChange
                }
                className="col form-select form-select-sm bg-light text-secondary border-0"
                style={{
                  width: "auto",
                }}
              >
                <option value="week">
                  یک هفته گذشته
                </option>

                <option value="month">
                  یک ماه گذشته
                </option>

                <option value="year">
                  یک سال گذشته
                </option>
              </select>

            </div>

            <div className="scrollable-list">

              {loading ? (
                <div className="text-center text-muted py-4">
                  در حال دریافت اطلاعات...
                </div>
              ) : displayedRepairmen.length === 0 ? (
                <div className="text-center text-muted py-4">
                  اطلاعاتی برای نمایش تعمیرکاران وجود ندارد.
                </div>
              ) : (
                <div className="d-flex flex-column gap-2">

                  {displayedRepairmen.map(
                    (repairman, index) => {

                      const name =
                        this.getRepairmanName(
                          repairman
                        );

                      const requestCount =
                        this.getRepairmanRequests(
                          repairman
                        );

                      return (
                        <div
                          key={
                            repairman.id ||
                            repairman.user_id ||
                            index
                          }
                          className="d-flex align-items-center gap-3 p-3 bg-light rounded-3"
                        >

                          <img
                            src={this.getRepairmanImage(
                              repairman
                            )}
                            alt={name}
                            className="rounded-circle"
                            width="40"
                            height="40"
                            style={{
                              objectFit: "cover",
                            }}
                            onError={(e) => {
                              e.currentTarget.src =
                                `https://ui-avatars.com/api/?name=${encodeURIComponent(
                                  name
                                )}&background=e9ecef&color=495057&size=40&rounded=true`;
                            }}
                          />

                          <div>

                            <div className="fw-semibold">
                              {name}
                            </div>

                            <div className="text-muted small">
                              {requestCount}{" "}
                              درخواست انجام شده
                            </div>

                          </div>

                        </div>
                      );
                    }
                  )}

                </div>
              )}

            </div>

          </div>

        </div>

      </main>
    );
  }
}

export default withRouter(Home);
